int _gcd(int a, int b)
{
	return !b ? a : _gcd(b, a%b);
}
int main()
{

	int x, y, limit;
	scanf("%d%d%d", &x, &y, &limit);
	double _MAX = 1e9;
	double _B = ((double)x) / y;
	int _Answer1, _Answer2;
